import{_ as s,C as n,o as e,c as o,a2 as l,b as E,w as a,a as i,E as d,a3 as B}from"./chunks/framework.BODD28Fk.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",m=JSON.parse('{"title":"납부 현황 집계","description":"","frontmatter":{},"headers":[],"relativePath":"payment/status.md","filePath":"payment/status.md","lastUpdated":1793459614000}'),g={name:"payment/status.md"};function C(h,t,f,_,u,c){const r=n("Mermaid");return e(),o("div",null,[t[1]||(t[1]=l('<h1 id="납부-현황-집계" tabindex="-1">납부 현황 집계 <a class="header-anchor" href="#납부-현황-집계" aria-label="Permalink to &quot;납부 현황 집계&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="프로젝트 수납 현황 및 회차별 총괄 집계 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/status.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>납부 현황 집계</strong> 페이지는 프로젝트의 전체 분양 수납 데이터를 차수별, 평형 타입별, 회차별로 다각도로 집계하여 실시간 통계와 채권 회수 분석 리포트를 제공하는 분양 수지 분석 센터입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [대금 수납 관리] → [납부 현황 집계]**를 선택하여 접속합니다.</li></ul>',4)),(e(),E(B,null,{default:a(()=>[d(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%93%85%20%EA%B8%B0%EC%A4%80%EC%9D%BC%EC%9E%90%20%EC%A7%80%EC%A0%95%3Cbr%3E(%EC%98%A4%EB%8A%98%20%EB%98%90%EB%8A%94%20%EA%B3%BC%EA%B1%B0%20%EC%9B%94%EB%A7%90%20%EA%B2%B0%EC%82%B0%EC%9D%BC)%22%5D%20--%3E%20B%7B%22%EB%A6%AC%ED%8F%AC%ED%8A%B8%20%EC%A2%85%EB%A5%98%20%EC%84%A0%ED%83%9D%22%7D%0A%20%20%20%20B%20--%20%22%20%ED%8F%89%ED%98%95%EB%B3%84%20%EB%A7%A4%EC%B6%9C%2F%EB%B6%84%EC%96%91%20%EC%84%B1%EA%B3%BC%20%22%20--%3E%20C%5B%22%F0%9F%93%8A%201.%20%EC%88%98%EB%82%A9%EC%9A%94%EC%95%BD%20%ED%83%AD%3Cbr%3E(%ED%83%80%EC%9E%85%EB%B3%84%20%EC%98%88%EC%82%B0%20%EB%8C%80%EB%B9%84%20%EA%B3%84%EC%95%BD%C2%B7%EC%88%98%EB%82%A9%C2%B7%EB%AF%B8%EB%B6%84%EC%96%91%20%EB%B6%84%EC%84%9D)%22%5D%0A%20%20%20%20B%20--%20%22%20%ED%9A%8C%EC%B0%A8%EB%B3%84%20%EC%9E%90%EA%B8%88%ED%9A%8C%EC%88%98%2F%EC%B1%84%EA%B6%8C%20%EA%B4%80%EB%A6%AC%20%22%20--%3E%20D%5B%22%F0%9F%93%88%202.%20%EC%B4%9D%EA%B4%84%EC%A7%91%EA%B3%84%20%ED%83%AD%3Cbr%3E(%EA%B8%B0%EA%B0%84%EB%8F%84%EB%9E%98%20%EC%97%B0%EC%B2%B4%EB%AF%B8%EC%88%98%20vs%20%EA%B8%B0%EA%B0%84%EB%AF%B8%EB%8F%84%EB%9E%98%20%EC%A0%95%EC%83%81%EB%AF%B8%EC%88%98)%22%5D%0A%20%20%20%20C%20%26%20D%20--%3E%20E%5B%22%F0%9F%93%91%20%EA%B2%BD%EC%98%81%EC%A7%84%20%EB%B3%B4%EA%B3%A0%EC%84%9C%20%26%20%EC%97%91%EC%85%80%20%EB%8B%A4%EC%9A%B4%EB%A1%9C%EB%93%9C%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-개요-및-2대-리포트-체계" tabindex="-1">1. 개요 및 2대 리포트 체계 <a class="header-anchor" href="#_1-개요-및-2대-리포트-체계" aria-label="Permalink to &quot;1. 개요 및 2대 리포트 체계&quot;">​</a></h2><p>특정 <strong>기준일자</strong>를 설정하여 해당 시점까지의 누적 수납 실적과 미수금 현황을 다각도로 분석합니다.</p><ul><li><strong>수납요약 리포트</strong>: 최초 수입 목표 예산 대비 실제 계약 성과와 실수납액, 미분양 물량을 평형 타입별로 입체 분석합니다.</li><li><strong>총괄집계 리포트</strong>: 분양 대금의 회차(계약금, 중도금, 잔금)별로 약정 기일 도래 여부에 따라 자금 회수율과 미수금(연체금)의 성격을 정밀 분석합니다.</li></ul><h2 id="_2-주요-기능" tabindex="-1">2. 주요 기능 <a class="header-anchor" href="#_2-주요-기능" aria-label="Permalink to &quot;2. 주요 기능&quot;">​</a></h2><ul><li><strong>기준일자 설정을 통한 시점별 실적 조회</strong>: 과거 특정 일자를 지정하여 당시의 수납 현황 보고서를 정확하게 재현</li><li><strong>타입별 분양 및 수납 현황 분석 (수납요약)</strong>: 타입별 세대수, 계약 세대, 계약액, 실수납액, 미수금, 미계약 잔여액 집계</li><li><strong>회차별 채권 회수 및 미수금 분석 (총괄집계)</strong>: 회차별 약정액, 기납부액, 기간도래 미수(연체), 기간미도래 미수(대기) 집계</li><li><strong>원클릭 엑셀 다운로드 지원</strong>: 집계된 통계표를 서식 그대로 엑셀 파일로 추출</li></ul><h2 id="_3-화면-구성-및-상세-분석-안내" tabindex="-1">3. 화면 구성 및 상세 분석 안내 <a class="header-anchor" href="#_3-화면-구성-및-상세-분석-안내" aria-label="Permalink to &quot;3. 화면 구성 및 상세 분석 안내&quot;">​</a></h2><h3 id="_1-기준일자-설정-바" tabindex="-1">1. 기준일자 설정 바 <a class="header-anchor" href="#_1-기준일자-설정-바" aria-label="Permalink to &quot;1. 기준일자 설정 바&quot;">​</a></h3><p>통계 산출의 기준이 되는 날짜를 지정합니다. 기본값은 오늘 날짜이며, 과거 날짜(예: 지난달 말일)를 선택하면 해당 일자 기준으로 수납 통계가 소급 재계산됩니다.</p><h3 id="_2-수납요약-탭" tabindex="-1">2. 수납요약 (탭) <a class="header-anchor" href="#_2-수납요약-탭" aria-label="Permalink to &quot;2. 수납요약 (탭)&quot;">​</a></h3><p>프로젝트의 세대수(물량)와 공급가액을 기준으로 계약 및 수납 성과를 평형 타입별로 보여줍니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">집계 항목</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>차수 / 타입</strong></td><td style="text-align:left;">프로젝트의 계약 그룹(1차, 일반) 및 평형 타입(59A, 84B 등)</td></tr><tr><td style="text-align:left;"><strong>전체 매출액</strong></td><td style="text-align:left;"><a href="/project/budgets.html">수입 예산 등록</a>에서 수립한 해당 타입의 총 목표 금액</td></tr><tr><td style="text-align:left;"><strong>계약 세대(실)수</strong></td><td style="text-align:left;">기준일 현재까지 체결 완료된 유효 계약 세대수</td></tr><tr><td style="text-align:left;"><strong>계약 금액</strong></td><td style="text-align:left;">체결된 계약 건들의 총 공급가액 합계</td></tr><tr><td style="text-align:left;"><strong>실수납 금액</strong></td><td style="text-align:left;">실제로 입금 처리 완료된 순수 납부 대금 합계</td></tr><tr><td style="text-align:left;"><strong>미수 금액</strong></td><td style="text-align:left;">계약된 금액 중 아직 입금되지 않고 남아있는 미납액</td></tr><tr><td style="text-align:left;"><strong>미계약 세대 / 금액</strong></td><td style="text-align:left;">전체 세대 중 아직 계약되지 않은 잔여 물량 및 잔여 공급 목표액</td></tr></tbody></table><h3 id="_3-총괄집계-탭" tabindex="-1">3. 총괄집계 (탭) <a class="header-anchor" href="#_3-총괄집계-탭" aria-label="Permalink to &quot;3. 총괄집계 (탭)&quot;">​</a></h3><p>각 납부 회차별(계약금, 중도금 1~6회차, 잔금 등) 약정 기준일에 따라 자금 회수 현황과 미수금의 성격을 분석합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">상세 집계 내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>기본 정보</strong></td><td style="text-align:left;">각 회차별 공식 납부 약정일(기준일) 표출</td></tr><tr><td style="text-align:left;"><strong>계약 현황</strong></td><td style="text-align:left;">계약분 금액, 미계약분 금액, 총계 및 현재 실계약률(%)</td></tr><tr><td style="text-align:left;"><strong>수납 현황</strong></td><td style="text-align:left;">정규 수납액, 선납 할인료, 연체료 가산액, 실수납액 및 누적 수납률(%)</td></tr><tr><td style="text-align:left;"><strong>기간도래 미수 (연체)</strong></td><td style="text-align:left;"><strong>약정일이 이미 지났음에도 수납되지 않은 순수 연체 미수금</strong> 및 발생 연체료 합계</td></tr><tr><td style="text-align:left;"><strong>기간미도래 미수 (정상)</strong></td><td style="text-align:left;">아직 약정일이 도래하지 않아 정상적으로 납부를 대기 중인 잔여 미수금</td></tr><tr><td style="text-align:left;"><strong>총계</strong></td><td style="text-align:left;">전체 미수금 합계 및 전체 분양가 대비 미수율(%)</td></tr></tbody></table><h2 id="_4-💡-실무-활용-가이드" tabindex="-1">4. 💡 실무 활용 가이드 <a class="header-anchor" href="#_4-💡-실무-활용-가이드" aria-label="Permalink to &quot;4. 💡 실무 활용 가이드&quot;">​</a></h2><ul><li><strong>💡 경영진 및 PF 대주단 정기 보고서 작성</strong>: <ul><li>월말 정기 결산 시 기준일자를 **&#39;해당 월의 말일&#39;**로 지정한 후 엑셀 다운로드를 실행하십시오. 과거 시점의 확정된 수납 실적이 오차 없이 정확하게 재현되어 신뢰성 높은 보고서를 즉시 작성할 수 있습니다.</li></ul></li><li><strong>💡 &#39;기간도래 미수&#39;를 활용한 연체 채권 관리</strong>: <ul><li>총괄집계 화면에서 <strong>&#39;기간도래 미수&#39;</strong> 금액이 크게 잡힌 회차는 약정일이 지났는데도 입금이 지연되고 있는 연체 세대입니다.</li><li>해당 회차의 연체자 명단을 추출하여 <a href="/notice/bill.html">고객 고지 관리 &gt; 수납 고지서 출력</a> 또는 <a href="/notice/sms.html">SMS 발송 관리</a>와 연계해 미납 안내문과 독촉 문자를 신속히 발송하십시오.</li></ul></li></ul>',16))])}const b=s(g,[["render",C]]);export{m as __pageData,b as default};
